--
-- Migration: **`bulk_jobs`**. One bulk import or export job (T-8, spec `bulk-import-export.md` §2). `UNIQUE (entity, kind, idempotency_key)` makes a retried request return the original job. The counters always reconcile: `rows_total = created + updated + unchanged + queued_for_review + failed`. A job is never deleted; only its artifacts expire.

CREATE TABLE IF NOT EXISTS "bulk_jobs" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "entity" varchar NOT NULL, "kind" varchar NOT NULL, "status" varchar NOT NULL, "format" varchar NOT NULL, "idempotency_key" varchar NULL, "requested_by" varchar NULL, "params" jsonb NOT NULL, "rows_total" bigint NOT NULL, "rows_created" bigint NOT NULL, "rows_updated" bigint NOT NULL, "rows_unchanged" bigint NOT NULL, "rows_queued_for_review" bigint NOT NULL, "rows_failed" bigint NOT NULL, "rows_omitted" bigint NOT NULL, "source_artifact" uuid NULL, "result_artifact" uuid NULL, "error_artifact" uuid NULL, "started_at" timestamp with time zone NULL, "finished_at" timestamp with time zone NULL, "failure_reason" text NULL );

ALTER TABLE bulk_jobs ADD CONSTRAINT bulk_jobs_kind CHECK (kind IN ('import','export'));

ALTER TABLE bulk_jobs ADD CONSTRAINT bulk_jobs_status CHECK (status IN ('queued','running','completed','completed_with_errors','failed'));

CREATE UNIQUE INDEX bulk_jobs_idempotency ON bulk_jobs (entity, kind, idempotency_key);

CREATE INDEX bulk_jobs_status_idx ON bulk_jobs (status, updated_at);
